// @FIGURE_CODE_BEGIN
// ─── element spec ────────────────────────────────────────────────────────────
// lateral surface    → custom BufferGeometry strip (unrollable), opaque WHITE MeshBasicMaterial, occluder only
// top rim outline    → TubeGeometry along (un)rolled circle, black, tube radius LW  (full ellipse)
// bottom rim outline → TubeGeometry, black, depth-tested → far arc hidden by occluder (partial ellipse)
// caps (net view)    → TorusGeometry(R, LW) black outline + CircleGeometry white disk occluder
// seam edges         → CylinderGeometry vertical bars, radius LW, black, depth-tested (hidden at back when rolled)
// silhouette edges   → CylinderGeometry vertical bars, radius LW, black, depthTest FALSE, placed at the exact
//                      perspective tangent points so they meet the rim ellipses with no gap
// radius arrow       → CylinderGeometry shaft (AW) + ConeGeometry head, black, depthTest false
// height arrow       → shaft + 2 cones + 2 end ticks, black, depthTest false, hugging the right silhouette
// net annotations    → shaft/cone/tick sets for r, h, 2*pi*r, black, depthTest false
// labels r, h, 2πr   → addLabel, italic serif
// ─────────────────────────────────────────────────────────────────────────────

const LW = 0.013;          // outline stroke radius (uniform everywhere) ≈ 2px at default framing
const AW = 0.012;          // annotation stroke radius (matches outline weight)
const HEAD_L = 0.18, HEAD_R = 0.058;
const Y_UP = new THREE.Vector3(0, 1, 0);

const MAT_BLACK = new THREE.MeshBasicMaterial({ color: 0x000000 });
const MAT_SIL = new THREE.MeshBasicMaterial({ color: 0x000000, depthTest: false, transparent: true, opacity: 1 });
const MAT_TOP = new THREE.MeshBasicMaterial({ color: 0x000000, depthTest: false });
const MAT_WHITE = new THREE.MeshBasicMaterial({
  color: 0xffffff, side: THREE.DoubleSide, depthWrite: true,
  polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1
});

/* ── small builders ─────────────────────────────────────────────────────── */
function segMesh(a, b, rad, mat) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = Math.max(dir.length(), 1e-4);
  const m = new THREE.Mesh(new THREE.CylinderGeometry(rad, rad, len, 8, 1), mat);
  m.position.copy(a).add(b).multiplyScalar(0.5);
  m.quaternion.setFromUnitVectors(Y_UP, dir.normalize());
  return m;
}
function coneMesh(tip, dir, len, rad, mat) {
  const dd = dir.clone().normalize();
  const m = new THREE.Mesh(new THREE.ConeGeometry(rad, len, 16), mat);
  m.position.copy(tip).addScaledVector(dd, -len / 2);
  m.quaternion.setFromUnitVectors(Y_UP, dd);
  return m;
}
function clearGroup(g) {
  for (let i = g.children.length - 1; i >= 0; i--) {
    const c = g.children[i];
    g.remove(c);
    c.geometry && c.geometry.dispose && c.geometry.dispose();
  }
}

/* ── unroll map: phi on the cylinder → point, t = 0 rolled, t = 1 flat ──── */
function unrollPt(rad, phi, t, y) {
  const k = (1 - t) / rad;
  const s = rad * phi;
  let ox, oz;
  if (k > 1e-6) { const Rc = 1 / k, ang = s * k; ox = Rc * (Math.cos(ang) - 1); oz = Rc * Math.sin(ang); }
  else { ox = 0; oz = s; }
  return new THREE.Vector3(rad + ox, y, oz);
}

function lateralGeom(r, h, t) {
  const N = 96, rr = Math.max(0.05, r - 0.02);   // sits just inside the outline: no z-fight with the rims
  const pos = new Float32Array((N + 1) * 2 * 3);
  const idx = [];
  for (let i = 0; i <= N; i++) {
    const phi = -Math.PI + 2 * Math.PI * i / N;
    const p = unrollPt(rr, phi, t, 0);
    pos[i * 6 + 0] = p.x; pos[i * 6 + 1] = 0; pos[i * 6 + 2] = p.z;
    pos[i * 6 + 3] = p.x; pos[i * 6 + 4] = h; pos[i * 6 + 5] = p.z;
  }
  for (let i = 0; i < N; i++) {
    const a = i * 2, b = i * 2 + 1, c = (i + 1) * 2, dd = (i + 1) * 2 + 1;
    idx.push(a, c, b, b, c, dd);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  g.setIndex(idx);
  return g;
}
function rimGeom(r, y, t) {
  const N = 120, pts = [];
  for (let i = 0; i <= N; i++) pts.push(unrollPt(r, -Math.PI + 2 * Math.PI * i / N, t, y));
  return new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts, false), N, LW, 8, false);
}

/* ── persistent scene objects ───────────────────────────────────────────── */
const lateral = new THREE.Mesh(new THREE.BufferGeometry(), MAT_WHITE);
lateral.renderOrder = 0;
const topRim = new THREE.Mesh(new THREE.BufferGeometry(), MAT_BLACK);
const botRim = new THREE.Mesh(new THREE.BufferGeometry(), MAT_BLACK);
topRim.renderOrder = 2; botRim.renderOrder = 2;
const seamA = new THREE.Mesh(new THREE.CylinderGeometry(LW, LW, 1, 8), MAT_BLACK);
const seamB = new THREE.Mesh(new THREE.CylinderGeometry(LW, LW, 1, 8), MAT_BLACK);
const silA = new THREE.Mesh(new THREE.CylinderGeometry(LW, LW, 1, 8), MAT_SIL);
const silB = new THREE.Mesh(new THREE.CylinderGeometry(LW, LW, 1, 8), MAT_SIL);
silA.renderOrder = 6; silB.renderOrder = 6;
scene.add(lateral, topRim, botRim, seamA, seamB, silA, silB);

function makeCap() {
  const g = new THREE.Group();
  const disk = new THREE.Mesh(new THREE.CircleGeometry(1, 96), MAT_WHITE);
  const ring = new THREE.Mesh(new THREE.TorusGeometry(1, LW, 8, 120), MAT_BLACK);
  ring.renderOrder = 2;
  g.add(disk, ring);
  g.userData = { disk, ring };
  return g;
}
const capTop = makeCap(), capBot = makeCap();
scene.add(capTop, capBot);

const radiusAnnot = new THREE.Group();   // on the top face, rotates to face the camera
const heightAnnot = new THREE.Group();   // hugs the right silhouette, re-placed each frame
scene.add(radiusAnnot, heightAnnot);
const netAnnot = new THREE.Group();      // r / h / 2πr arrows on the flat net
let netInScene = false;

/* ── labels ─────────────────────────────────────────────────────────────── */
const SERIF = "font-family:Georgia,'Times New Roman',serif";
const lblR = addLabel(`<i style="${SERIF}">r</i>`, new THREE.Vector3(), { fontSize: '18px' });
const lblH = addLabel(`<i style="${SERIF}">h</i>`, new THREE.Vector3(), { fontSize: '18px' });
const lblRn = addLabel(`<i style="${SERIF}">r</i>`, new THREE.Vector3(), { fontSize: '17px' });
const lblHn = addLabel(`<i style="${SERIF}">h</i>`, new THREE.Vector3(), { fontSize: '17px' });
const lblC = addLabel(`2&pi;<i style="${SERIF}">r</i>`, new THREE.Vector3(), { fontSize: '17px' });
function labVis(e, on) { e.div.style.visibility = on ? 'visible' : 'hidden'; }

/* ── state ──────────────────────────────────────────────────────────────── */
let R = 1.6, H = 2.0, T = 0;          // current (animated)
let tR = 1.6, tH = 2.0, tT = 0;       // targets
let lastR = -1, lastH = -1, lastT = -1;
let annotR = -1, annotH = -1;

const QS = new THREE.Quaternion().setFromEuler(new THREE.Euler(-Math.PI / 2, 0, 0));
const QN = new THREE.Quaternion().setFromEuler(new THREE.Euler(0, Math.PI / 2, 0));
const smooth = (x) => x * x * (3 - 2 * x);

function capY() { return H + 0.6 + R; }
function capZ() { return R + 0.35; }

/* ── build / rebuild ────────────────────────────────────────────────────── */
function rebuildShape() {
  lateral.geometry.dispose(); lateral.geometry = lateralGeom(R, H, T);
  topRim.geometry.dispose(); topRim.geometry = rimGeom(R, H, T);
  botRim.geometry.dispose(); botRim.geometry = rimGeom(R, 0, T);

  const pA = unrollPt(R, Math.PI, T, 0), pB = unrollPt(R, -Math.PI, T, 0);
  seamA.geometry.dispose(); seamA.geometry = new THREE.CylinderGeometry(LW, LW, H, 8);
  seamB.geometry.dispose(); seamB.geometry = new THREE.CylinderGeometry(LW, LW, H, 8);
  seamA.position.set(pA.x, H / 2, pA.z);
  seamB.position.set(pB.x, H / 2, pB.z);

  silA.geometry.dispose(); silA.geometry = new THREE.CylinderGeometry(LW, LW, H, 8);
  silB.geometry.dispose(); silB.geometry = new THREE.CylinderGeometry(LW, LW, H, 8);

  // caps: hinge flat as the net opens
  const e = smooth(Math.min(1, Math.max(0, T)));
  const cy = capY(), cz = capZ();
  capTop.position.lerpVectors(new THREE.Vector3(0, H, 0), new THREE.Vector3(R, cy, cz), e);
  capBot.position.lerpVectors(new THREE.Vector3(0, 0, 0), new THREE.Vector3(R, cy, -cz), e);
  capTop.quaternion.slerpQuaternions(QS, QN, e);
  capBot.quaternion.slerpQuaternions(QS, QN, e);
  for (const c of [capTop, capBot]) {
    c.userData.disk.geometry.dispose();
    c.userData.disk.geometry = new THREE.CircleGeometry(Math.max(0.05, R - 0.02), 96);
    c.userData.ring.geometry.dispose();
    c.userData.ring.geometry = new THREE.TorusGeometry(R, LW, 8, 120);
  }
}

function rebuildSolidAnnot() {
  // radius arrow: centre of the top face → rim; local +X is screen-right
  clearGroup(radiusAnnot);
  radiusAnnot.add(segMesh(new THREE.Vector3(0, H, 0), new THREE.Vector3(Math.max(0.02, R - HEAD_L * 0.8), H, 0), AW, MAT_TOP));
  radiusAnnot.add(coneMesh(new THREE.Vector3(R, H, 0), new THREE.Vector3(1, 0, 0), HEAD_L, HEAD_R, MAT_TOP));
  radiusAnnot.traverse(o => { o.renderOrder = 12; });

  // height arrow (built about its own local origin; placed beside the silhouette each frame)
  clearGroup(heightAnnot);
  heightAnnot.add(segMesh(new THREE.Vector3(0, HEAD_L * 0.8, 0), new THREE.Vector3(0, H - HEAD_L * 0.8, 0), AW, MAT_TOP));
  heightAnnot.add(coneMesh(new THREE.Vector3(0, H, 0), new THREE.Vector3(0, 1, 0), HEAD_L, HEAD_R, MAT_TOP));
  heightAnnot.add(coneMesh(new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, -1, 0), HEAD_L, HEAD_R, MAT_TOP));
  heightAnnot.add(segMesh(new THREE.Vector3(-0.12, H, 0), new THREE.Vector3(0.12, H, 0), AW, MAT_TOP));
  heightAnnot.add(segMesh(new THREE.Vector3(-0.12, 0, 0), new THREE.Vector3(0.12, 0, 0), AW, MAT_TOP));
  heightAnnot.traverse(o => { o.renderOrder = 12; });
}

function rebuildNetAnnot() {
  clearGroup(netAnnot);
  const x = R + 0.04, right = new THREE.Vector3(0, 0, -1);
  const cy = capY(), cz = capZ();
  // r across the upper cap
  const c = new THREE.Vector3(x, cy, cz);
  const tip = c.clone().addScaledVector(right, R);
  netAnnot.add(segMesh(c, tip.clone().addScaledVector(right, -HEAD_L * 0.8), AW, MAT_TOP));
  netAnnot.add(coneMesh(tip, right, HEAD_L, HEAD_R, MAT_TOP));
  // h on the right edge of the rectangle
  const zh = -(Math.PI * R + 0.5);
  netAnnot.add(segMesh(new THREE.Vector3(x, HEAD_L * 0.8, zh), new THREE.Vector3(x, H - HEAD_L * 0.8, zh), AW, MAT_TOP));
  netAnnot.add(coneMesh(new THREE.Vector3(x, H, zh), new THREE.Vector3(0, 1, 0), HEAD_L, HEAD_R, MAT_TOP));
  netAnnot.add(coneMesh(new THREE.Vector3(x, 0, zh), new THREE.Vector3(0, -1, 0), HEAD_L, HEAD_R, MAT_TOP));
  netAnnot.add(segMesh(new THREE.Vector3(x, H, zh - 0.12), new THREE.Vector3(x, H, zh + 0.12), AW, MAT_TOP));
  netAnnot.add(segMesh(new THREE.Vector3(x, 0, zh - 0.12), new THREE.Vector3(x, 0, zh + 0.12), AW, MAT_TOP));
  // 2πr under the rectangle
  const yw = -0.55, z0 = Math.PI * R, z1 = -Math.PI * R;
  netAnnot.add(segMesh(new THREE.Vector3(x, yw, z0 - HEAD_L * 0.8), new THREE.Vector3(x, yw, z1 + HEAD_L * 0.8), AW, MAT_TOP));
  netAnnot.add(coneMesh(new THREE.Vector3(x, yw, z0), new THREE.Vector3(0, 0, 1), HEAD_L, HEAD_R, MAT_TOP));
  netAnnot.add(coneMesh(new THREE.Vector3(x, yw, z1), new THREE.Vector3(0, 0, -1), HEAD_L, HEAD_R, MAT_TOP));
  netAnnot.add(segMesh(new THREE.Vector3(x, yw - 0.12, z0), new THREE.Vector3(x, yw + 0.12, z0), AW, MAT_TOP));
  netAnnot.add(segMesh(new THREE.Vector3(x, yw - 0.12, z1), new THREE.Vector3(x, yw + 0.12, z1), AW, MAT_TOP));
  netAnnot.traverse(o => { o.renderOrder = 12; });
}

rebuildShape(); rebuildSolidAnnot(); rebuildNetAnnot();
lastR = R; lastH = H; lastT = T; annotR = R; annotH = H;

/* ── camera ─────────────────────────────────────────────────────────────── */
setCameraView({ projection: 'perspective', azimuthDeg: 0, elevationDeg: 18, rollDeg: 0, heightFraction: 0.68 });
controls.minPolarAngle = THREE.MathUtils.degToRad(30);   // elevation ≤ 60°
controls.maxPolarAngle = THREE.MathUtils.degToRad(90);   // elevation ≥ 0°
controls.update();

function refit() {
  const off = camera.position.clone().sub(controls.target);
  const len = off.length() || 1;
  const az = THREE.MathUtils.radToDeg(Math.atan2(off.z, off.x));
  const el = THREE.MathUtils.radToDeg(Math.asin(THREE.MathUtils.clamp(off.y / len, -1, 1)));
  setCameraView({ projection: 'perspective', azimuthDeg: az, elevationDeg: el, heightFraction: 0.68 });
}

/* ── exact perspective silhouette tangent points of the vertical cylinder ── */
const _sil = { ax: 0, az: 0, bx: 0, bz: 0, rx: 1, rz: 0, rotY: 0 };
function updateSilhouetteFrame(r) {
  const cx = camera.position.x, cz = camera.position.z;
  const Dh = Math.hypot(cx, cz);
  let ux, uz;
  if (Dh < 1e-6) { ux = 1; uz = 0; } else { ux = cx / Dh; uz = cz / Dh; }
  const s = Dh > r * 1.02 ? r / Dh : 0.98;             // cos of the tangent half-angle
  const sn = Math.sqrt(Math.max(0, 1 - s * s));
  const lx = -uz, lz = ux;                              // screen-LEFT horizontal direction
  const rx = uz, rz = -ux;                              // screen-RIGHT horizontal direction
  _sil.ax = r * (s * ux + sn * lx); _sil.az = r * (s * uz + sn * lz);   // left tangent
  _sil.bx = r * (s * ux + sn * rx); _sil.bz = r * (s * uz + sn * rz);   // right tangent
  _sil.rx = rx; _sil.rz = rz;
  _sil.rotY = Math.atan2(ux, uz);                       // maps local +X → screen-right
}

/* ── interactive explainers ─────────────────────────────────────────────── */
registerInteractive(lateral, {
  title: 'The lateral (side) surface',
  tooltip: 'Side wall — unrolls to a rectangle',
  body: 'Cut this wall along a vertical seam and flatten it: you get a rectangle 2πr wide (the rim circumference) and h tall, so its area is 2πrh.'
});
registerInteractive(capTop, {
  title: 'Circular cap',
  tooltip: 'Top face — a circle of radius r',
  body: 'The top and bottom faces are congruent circles of radius r. Each has area πr², so together they contribute 2πr². Added to the side, S = 2πr² + 2πrh = 2πr(r + h).'
});

/* ── readout ────────────────────────────────────────────────────────────── */
const readout = document.getElementById('readout');
function updateReadout() {
  const caps = 2 * Math.PI * tR * tR;
  const side = 2 * Math.PI * tR * tH;
  readout.innerHTML =
    `<b>S = 2&pi;r(r + h)</b><br>` +
    `= 2&pi;(${tR.toFixed(2)})(${tR.toFixed(2)} + ${tH.toFixed(2)}) <b>&asymp; ${(caps + side).toFixed(2)}</b><br>` +
    `<span style="color:#555">caps 2&pi;r&sup2; &asymp; ${caps.toFixed(2)} &nbsp;&middot;&nbsp; side 2&pi;rh &asymp; ${side.toFixed(2)}</span>`;
}

/* ── per-frame update ───────────────────────────────────────────────────── */
let prevTime = performance.now();
const _p = new THREE.Vector3();

function frame() {
  requestAnimationFrame(frame);
  const now = performance.now();
  const dt = Math.min(0.05, (now - prevTime) / 1000);
  prevTime = now;

  const kA = 1 - Math.exp(-dt * 9);
  const kT = 1 - Math.exp(-dt * 4.5);
  if (Math.abs(tR - R) > 1e-4) R += (tR - R) * kA; else R = tR;
  if (Math.abs(tH - H) > 1e-4) H += (tH - H) * kA; else H = tH;
  if (Math.abs(tT - T) > 1e-4) T += (tT - T) * kT; else T = tT;

  const changed = Math.abs(R - lastR) > 1e-5 || Math.abs(H - lastH) > 1e-5 || Math.abs(T - lastT) > 1e-5;
  if (changed) {
    if (Math.abs(R - annotR) > 1e-5 || Math.abs(H - annotH) > 1e-5) {
      rebuildSolidAnnot(); rebuildNetAnnot(); annotR = R; annotH = H;
    }
    rebuildShape();
    lastR = R; lastH = H; lastT = T;
  }

  // net annotations enter/leave the scene (keeps the auto-fit bounds honest)
  const wantNet = T > 0.5;
  if (wantNet !== netInScene) { netInScene = wantNet; if (wantNet) scene.add(netAnnot); else scene.remove(netAnnot); }
  radiusAnnot.visible = heightAnnot.visible = !wantNet;

  if (changed) refit();

  // silhouette bars: exact tangents, drawn on top so they never z-fight the white wall
  updateSilhouetteFrame(R);
  silA.position.set(_sil.ax, H / 2, _sil.az);
  silB.position.set(_sil.bx, H / 2, _sil.bz);
  const fade = Math.max(0, 1 - T * 4);
  MAT_SIL.opacity = fade;
  silA.visible = silB.visible = fade > 0.02;

  // annotations face the camera
  const rotY = _sil.rotY;
  radiusAnnot.rotation.y = rotY;
  const hx = _sil.bx + _sil.rx * 0.22, hz = _sil.bz + _sil.rz * 0.22;
  heightAnnot.position.set(hx, 0, hz);
  heightAnnot.rotation.y = rotY;

  // labels
  _p.set(0.72 * R, H, 0).applyAxisAngle(Y_UP, rotY);
  lblR.pos.copy(_p); lblR.offset = [0, -13];
  lblH.pos.set(hx, H / 2, hz); lblH.offset = [15, 0];

  const cy = capY(), cz = capZ();
  lblRn.pos.set(R + 0.05, cy, cz - 0.55 * R); lblRn.offset = [0, -13];
  lblHn.pos.set(R + 0.05, H / 2, -(Math.PI * R + 0.5)); lblHn.offset = [16, 0];
  lblC.pos.set(R + 0.05, -0.55, 0); lblC.offset = [0, 17];

  labVis(lblR, !wantNet); labVis(lblH, !wantNet);
  labVis(lblRn, wantNet); labVis(lblHn, wantNet); labVis(lblC, wantNet);
}
frame();

/* ── controls ───────────────────────────────────────────────────────────── */
const inR = document.getElementById('radius');
const inH = document.getElementById('height');
const spR = document.getElementById('rVal');
const spH = document.getElementById('hVal');
const btnSolid = document.getElementById('viewSolid');
const btnNet = document.getElementById('viewNet');

function syncView() {
  btnSolid.classList.toggle('active', tT < 0.5);
  btnNet.classList.toggle('active', tT >= 0.5);
}
inR.addEventListener('input', () => { tR = parseFloat(inR.value); spR.textContent = tR.toFixed(2); updateReadout(); });
inH.addEventListener('input', () => { tH = parseFloat(inH.value); spH.textContent = tH.toFixed(2); updateReadout(); });
btnSolid.addEventListener('click', () => { tT = 0; syncView(); });
btnNet.addEventListener('click', () => { tT = 1; syncView(); });
document.getElementById('resetView').addEventListener('click', () => {
  setCameraView({ projection: 'perspective', azimuthDeg: 0, elevationDeg: 18, rollDeg: 0, heightFraction: 0.68 });
  controls.minPolarAngle = THREE.MathUtils.degToRad(30);
  controls.maxPolarAngle = THREE.MathUtils.degToRad(90);
});

/* ── guided steps ───────────────────────────────────────────────────────── */
const steps = [
  {
    title: 'The two measurements',
    narration: 'A right circular cylinder outlined in black. One arrow runs from the centre of the top face out to its rim — that is r. A second arrow just outside the body runs from the top rim to the bottom rim — that is h.',
    state: { radius: 1.6, height: 2.0, view: 'solid cylinder' }
  },
  {
    title: 'Grow r',
    narration: 'Dragging r wide makes the caps larger AND the distance around the rim larger, so both the πr² caps and the 2πrh side grow — the surface area climbs quickly.',
    state: { radius: 2.4, height: 2.0, view: 'solid cylinder' }
  },
  {
    title: 'Grow h',
    narration: 'Return r and stretch h instead: the top and bottom circles never change size. Only the side wall gets taller, so surface area grows in simple proportion to h.',
    state: { radius: 1.6, height: 3.2, view: 'solid cylinder' }
  },
  {
    title: 'Unroll the surface',
    narration: 'Cut the side and flatten it: two circles of radius r plus a rectangle 2πr wide and h tall. That is 2πr² + 2πrh = 2πr(r + h).',
    state: { radius: 1.6, height: 2.0, view: 'unrolled net' }
  }
];
let stepIdx = 0;
const elTitle = document.getElementById('stepTitle');
const elText = document.getElementById('stepText');

function goToStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  const s = steps[stepIdx];
  tR = s.state.radius; tH = s.state.height; tT = (s.state.view === 'unrolled net') ? 1 : 0;
  inR.value = String(tR); inH.value = String(tH);
  spR.textContent = tR.toFixed(2); spH.textContent = tH.toFixed(2);
  syncView(); updateReadout();
  elTitle.textContent = `${stepIdx + 1}. ${s.title}`;
  elText.textContent = s.narration;
}
document.getElementById('stepPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('stepNext').addEventListener('click', () => goToStep(stepIdx + 1));

goToStep(0);
